css:
.s4-stage, .m3-stage { border: 2px solid var(--ink); border-radius: 12px; overflow: hidden; background: #0f1630; }
.s4-home, .m3-home { position: absolute; right: 14px; top: 12px; font-size: 19px !important; padding: 8px 14px !important; }
.s4-out, .m3-out { margin: 0; font-size: 21px; line-height: 1.5; background: #fffbe6; border: 2px solid var(--accent); border-radius: 12px; padding: 8px 14px; min-height: 2.2em; }
.s4-out small { display: block; margin-top: 4px; font-size: 18px; color: var(--ink-2); }
.m3-kind button { font-size: 19px; }
.m3-row { display: grid; grid-template-columns: minmax(0, 1fr) 150px; gap: 10px; align-items: start; }
.m3-table { width: 100%; border-collapse: collapse; font-size: 19px; }
.m3-table th, .m3-table td { border: 1.5px solid var(--rule); padding: 4px 8px; text-align: left; }
.m3-table th { background: color-mix(in srgb, var(--accent) 12%, #fff); white-space: nowrap; font-weight: 700; }
.m3-bar { display: block; height: 14px; background: var(--paper-2, #eee); border-radius: 7px; overflow: hidden; }
.m3-bar i { display: block; height: 100%; background: #2f9e5b; transition: width .4s; }
.m3-photo { margin: 0; }
.m3-photo img { width: 150px; height: 120px; object-fit: cover; border-radius: 10px; border: 2px solid var(--ink); }

